<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/seo/PublicSitemap.php';
function seo_check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$db->exec("CREATE TABLE destinations(id INTEGER,slug TEXT,publication_status TEXT);CREATE TABLE destination_translations(destination_id INTEGER,locale TEXT);CREATE TABLE businesses(id INTEGER,public_id TEXT,destination_id INTEGER,category_code TEXT,publication_status TEXT,information_status TEXT,operation_status TEXT);CREATE TABLE business_translations(business_id INTEGER,locale TEXT);CREATE TABLE service_category_translations(category_code TEXT,locale TEXT);CREATE TABLE business_subscriptions(id INTEGER,business_id INTEGER,plan_code TEXT,status TEXT,starts_at TEXT,ends_at TEXT);CREATE TABLE subscription_plans(code TEXT,has_business_page INTEGER);CREATE TABLE subscription_plan_features(plan_code TEXT,feature_code TEXT,included INTEGER);
INSERT INTO destinations VALUES(1,'jerico','published'),(2,'draft','draft');INSERT INTO destination_translations VALUES(1,'es'),(1,'en'),(2,'es');INSERT INTO businesses VALUES(1,'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee',1,'cafe','published','PUBLICO','ABIERTO');INSERT INTO business_translations VALUES(1,'es');INSERT INTO service_category_translations VALUES('cafe','es');INSERT INTO subscription_plans VALUES('page',1),('free',0),('featured',0);INSERT INTO subscription_plan_features VALUES('page','business_page',1),('featured','highlighted_card',1);INSERT INTO business_subscriptions VALUES(1,1,'page','active',NULL,NULL)");
$s=new PublicSitemap($db);$base='https://example.invalid';
$seed='<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://example.invalid/</loc></url><url><loc>https://example.invalid/destinos/draft/</loc></url><url><loc>https://example.invalid/admin/index.php</loc></url><url><loc>https://example.invalid/?id=1</loc></url><url><loc>https://example.invalid/negocios/old/</loc></url></urlset>';
$x=$s->xml($base,$seed);seo_check(str_contains($x,'/en/destinos/jerico/'),'actual translation');seo_check(!str_contains($x,'/pt-br/'),'no invented languages');seo_check(!str_contains($x,'draft')&&!str_contains($x,'/admin/')&&!str_contains($x,'?id=')&&!str_contains($x,'/old/'),'exclude stale and private');seo_check(str_contains($x,'/negocios/aaaaaaaa-'),'active business page');
$db->exec("UPDATE business_subscriptions SET ends_at='2000-01-01'");seo_check(!str_contains($s->xml($base,$seed),'/negocios/'),'expired page removed');
$db->exec("UPDATE business_subscriptions SET ends_at=NULL,plan_code='featured'");seo_check(!str_contains($s->xml($base,$seed),'/negocios/'),'featured without page excluded');
$db->exec("UPDATE business_subscriptions SET plan_code='page',status='pending_payment'");seo_check(!str_contains($s->xml($base,$seed),'/negocios/'),'pending payment excluded');
$db->exec("UPDATE business_subscriptions SET status='active';UPDATE businesses SET publication_status='draft'");seo_check(!str_contains($s->xml($base,$seed),'/negocios/'),'draft business excluded');
$db->exec("UPDATE businesses SET publication_status='published';UPDATE destinations SET publication_status='archived' WHERE id=1");seo_check(!str_contains($s->xml($base,$seed),'/destinos/jerico/')&&!str_contains($s->xml($base,$seed),'/negocios/'),'archive removes destination and businesses automatically');
foreach(['<!DOCTYPE x [<!ENTITY x SYSTEM "file:///etc/passwd">]><urlset/>','broken'] as $bad){$rejected=false;try{$s->xml($base,$bad);}catch(Throwable){$rejected=true;}seo_check($rejected,'invalid XML rejected');}
echo "SEO sitemap: OK — publication, archive, translations, current entitlements, stale URLs and XML safety.\n";
